// ppwr - split the token into its three parts
//
// The token is <campaign_item_id>.<expires_ms>.<signature>. Nothing here is trusted: the parts
// are only used to rebuild the payload the signature should cover and to look up a row. A forged
// token gets as far as a database miss and no further.

const submitted = $input.first().json || {};

// The hidden field's key depends on how the Form Trigger names it, and guessing wrong would make
// every token look malformed. Take the declared name if it is there, otherwise find the one value
// on the item that has the shape of a token.
function findToken(source) {
  for (const key of ['t', 'token', 'T']) {
    if (typeof source[key] === 'string' && source[key].trim() !== '') return source[key].trim();
  }
  for (const value of Object.values(source)) {
    if (typeof value === 'string' && /^[^.]+\.\d+\.[^.]+$/.test(value.trim())) return value.trim();
  }
  return '';
}

const raw = findToken(submitted);
const parts = raw.split('.');
const wellFormed =
  parts.length === 3 && parts[0].length > 0 && /^\d+$/.test(parts[1]) && parts[2].length > 0;

if (!wellFormed) {
  // A placeholder payload, not a shortcut. The Crypto node downstream throws on an undefined
  // input, so a malformed token would crash before the verifier could reject it politely. This
  // signs a constant that can never match a real signature, and the verdict node does the work.
  return [
    {
      json: {
        token_ok: false,
        token: raw,
        token_payload: 'malformed',
        presented_signature: '',
        campaign_item_id: null,
        expires_ms: 0,
        expired: true,
        submitted_keys: Object.keys(submitted),
      },
    },
  ];
}

const [campaignItemId, expiresMs, signature] = parts;

return [
  {
    json: {
      token: raw,
      campaign_item_id: campaignItemId,
      expires_ms: Number(expiresMs),
      presented_signature: signature,
      token_payload: campaignItemId + '|' + expiresMs,
      expired: Number(expiresMs) < Date.now(),
      token_ok: true,
    },
  },
];

// ppwr - decide whether this link may proceed
//
// Four questions, and the visitor is told the answer to none of them. A probe that can tell
// "expired" from "never existed" from "wrong signature" learns which ids are real.

const decoded = $('Decode token').first().json;
const hashed = $('Hash presented token').first().json;
const lookup = $input.first().json;

const row = lookup && lookup.ok && lookup.rows && lookup.rows.length === 1 ? lookup.rows[0] : null;

// Constant time is not achievable in a Code node and is not the threat here: the signature is
// never revealed, only compared. A plain comparison is honest about what it is.
const signatureMatches =
  decoded.token_ok === true &&
  String(hashed.expected_sig || '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '') === decoded.presented_signature;

const OPEN_STATES = ['invited', 'opened', 'partial', 'gapped'];

const reasons = [];
if (!decoded.token_ok) reasons.push('malformed');
if (!signatureMatches) reasons.push('bad_signature');
if (decoded.expired) reasons.push('expired');
if (!row) reasons.push('no_matching_token');
else if (!OPEN_STATES.includes(row.state)) reasons.push(`state_${row.state}`);

const valid = reasons.length === 0;

return [
  {
    json: {
      valid,
      // Kept for the execution log and the operator, never shown to the visitor.
      reasons,
      campaign_item_id: row ? row.campaign_item_id : decoded.campaign_item_id,
      campaign_id: row ? row.campaign_id : null,
      item_id: row ? row.item_id : null,
      state: row ? row.state : null,
      next_revision: row ? row.next_revision : null,
      token: decoded.token,
    },
  },
];

// ppwr - build page 2 from the ruleset field catalogue
//
// The form does not hardcode its questions. Adding a field to the catalogue adds it here, which
// is the same promise the rule engine makes: change one JSON file, change nothing else.
//
// The catalogue is inlined for now. Once the campaign carries a frozen ruleset, this reads it
// from the store instead and the two can never drift.

const item = ($input.first().json || {}).row || {};
const foodContact = item.food_contact === true;

const CATALOGUE = {
  supplier_legal_name: { label: 'Supplier legal name', type: 'text', required: true },
  supplier_vat_number: { label: 'VAT number', type: 'text' },
  item_description: { label: 'Item description', type: 'text', required: true },
  packaging_level: { label: 'Packaging level', type: 'dropdown', values: ['sales', 'grouped', 'transport'] },
  primary_material: {
    label: 'Primary material',
    type: 'dropdown',
    values: ['paper_board', 'plastic', 'glass', 'metal', 'wood', 'composite', 'other'],
    required: true,
  },
  coating_present: { label: 'Is a coating present?', type: 'dropdown', values: ['yes', 'no'] },
  coating_type: { label: 'Coating type, if any', type: 'text' },
  pfas_intentionally_added: {
    label: 'Were PFAS intentionally added?',
    type: 'dropdown',
    values: ['yes', 'no'],
    required: true,
    foodContactOnly: true,
  },
  pfas_concentration_ppm: { label: 'PFAS concentration in ppm, if added', type: 'number', foodContactOnly: true },
  bpa_status: {
    label: 'Bisphenol status',
    type: 'dropdown',
    values: ['none_used', 'bisphenols_listed', 'not_applicable'],
    foodContactOnly: true,
  },
  bpa_transition_route: {
    label: 'Bisphenol transition route',
    type: 'dropdown',
    values: ['main', 'reusable', 'single_use_derogation', 'none'],
    foodContactOnly: true,
  },
  declaration_date: { label: 'Declaration date', type: 'date', required: true },
  declaration_signatory: { label: 'Who signed the declaration', type: 'text', required: true },
};

const fields = [];
for (const [name, spec] of Object.entries(CATALOGUE)) {
  // Substance questions only reach a supplier whose item touches food. Asking a carton maker
  // about bisphenols is how a form earns a reputation for wasting time.
  if (spec.foodContactOnly && !foodContact) continue;

  const field = {
    fieldLabel: spec.label,
    fieldName: name,
    fieldType: spec.type,
    requiredField: spec.required === true,
  };
  if (spec.type === 'dropdown') {
    field.fieldOptions = { values: spec.values.map((v) => ({ option: v })) };
  }
  fields.push(field);
}

return [
  {
    json: {
      food_contact: foodContact,
      item_description: item.description || null,
      internal_sku: item.internal_sku || null,
      form_fields: fields,
    },
  },
];

// ppwr - collect the answers into one submission payload
//
// Page 2's field names come from the catalogue, so whatever the supplier answered lands here
// under the same names the rule engine expects. Nothing is renamed on the way through.

const verified = $('Token valid?').first().json;
const page2 = $('Page 2: item and materials').first().json || {};
const page3 = $input.first().json || {};

const KNOWN = [
  'supplier_legal_name', 'supplier_vat_number', 'item_description', 'packaging_level',
  'primary_material', 'coating_present', 'coating_type', 'pfas_intentionally_added',
  'pfas_concentration_ppm', 'bpa_status', 'bpa_transition_route', 'declaration_date',
  'declaration_signatory',
];

const rawPayload = {};
for (const name of KNOWN) {
  if (page2[name] === undefined || page2[name] === '') continue;
  rawPayload[name] = page2[name];
}

// The form gives yes and no for booleans. The engine's value domain understands both, so they
// are passed through rather than translated here: one place decides what a boolean is.

const binaryKeys = Object.keys(page3).filter((k) => k !== 'submittedAt' && k !== 'formMode');

return [
  {
    json: {
      campaign_item_id: verified.campaign_item_id,
      revision: verified.next_revision || 1,
      raw_payload: rawPayload,
      submitted_by: rawPayload.declaration_signatory || null,
      answered_fields: Object.keys(rawPayload).length,
      attachment_keys: binaryKeys,
    },
  },
];

// ppwr - one item per uploaded file
//
// Files are recorded before anything is screened. A supplier who uploads four documents and then
// trips a validation rule must not have to find and attach them again, so the evidence is
// captured the moment it arrives and the verdict comes later.
//
// A submission with no attachments is normal, not an error: the rule engine decides whether a
// missing document is a gap, and it needs a submission row to say so against.
//
// Neither the hash nor the byte count is computed here. Both come back from ppwr-evidence, which
// derives them from the bytes it actually wrote. n8n reports a binary's size as a human string
// such as "212 kB", and a rounded byte count in an audit record is a number nobody can check.

const submissionId = $input.first().json.row ? $input.first().json.row.submission_id : null;
if (!submissionId) throw new Error('No submission row to attach documents to.');

const page = $('Page 3: evidence and attestation').first();
const binaries = page.binary || {};
const names = Object.keys(binaries);

if (names.length === 0) {
  return [{ json: { submission_id: submissionId, no_documents: true } }];
}

return names.map((key) => ({
  json: {
    submission_id: submissionId,
    binary_key: key,
    filename: binaries[key].fileName || key,
    mime_type: binaries[key].mimeType || null,
    // Every upload is filed as `other` until extraction reads it. Guessing a doc_type from a
    // filename would put a supplier's invoice in the declaration slot and pass the check.
    doc_type: 'other',
  },
  binary: { data: binaries[key] },
}));

// ppwr - pair each stored file with the upload it came from
//
// The evidence store answers with an address, a digest and a measured size, and knows nothing
// about submissions. The split node knows the submission and the declared filename. Neither
// half is a complete document row.
//
// Paired by position rather than by n8n's paired item tracking: the Execute Workflow node runs
// once per item and returns them in order, and an index is something this code can assert on.

const uploads = $('Split uploaded files').all().map((item) => item.json);
const stored = $input.all().map((item) => item.json);

if (stored.length !== uploads.length) {
  throw new Error(
    `The evidence store answered for ${stored.length} of ${uploads.length} uploads. Refusing to write document rows that would point at the wrong files.`
  );
}

return stored.map((evidence, index) => {
  const upload = uploads[index];
  if (!evidence || !evidence.uri || !evidence.sha256) {
    throw new Error(`The evidence store returned no address for '${upload.filename}'.`);
  }
  return {
    json: {
      submission_id: upload.submission_id,
      doc_type: upload.doc_type,
      filename: upload.filename,
      mime_type: evidence.mime_type || upload.mime_type,
      byte_size: evidence.byte_size,
      sha256: evidence.sha256,
      storage_uri: evidence.uri,
    },
  };
});

// ppwr - put the metadata back on the payload
//
// Verified against a live instance: extractFromFile replaces the item json with just its
// destination key, so the filename and mime type the split node worked out are gone by the time
// the evidence store is called. They are read back from the split node and paired by position.
//
// Position rather than n8n's paired item tracking, for the same reason the document rows are:
// the nodes in between run once per item and return them in order, and an index is something
// this code can assert on.

const uploads = $('Split uploaded files').all().map((item) => item.json);
const payloads = $input.all().map((item) => item.json);

if (payloads.length !== uploads.length) {
  throw new Error(
    `Converted ${payloads.length} of ${uploads.length} uploads to base64. Refusing to store bytes under the wrong filename.`
  );
}

return payloads.map((payload, index) => ({
  json: {
    filename: uploads[index].filename,
    mime_type: uploads[index].mime_type,
    content_b64: payload.content_b64,
  },
}));
